use super::*;
fn engine()->Engine {Engine::from_catalogue_bytes(include_bytes!(concat!(env!("OUT_DIR"),"/catalogue.json"))).unwrap()}
fn add(e:&Engine,s:&mut State,o:Seat,c:&str)->CardId{let id=s.next_id;s.next_id+=1;*s.card_mut(id)=Card{present:true,owner:o,def:e.by_code[c],..Card::default()};id}
fn unit(e:&Engine,s:&mut State,o:Seat,c:&str)->CardId{let id=add(e,s,o,c);e.add_arena(s,id).unwrap();id}
fn hand(e:&Engine,s:&mut State,o:Seat,c:&str)->CardId{let id=add(e,s,o,c);s.player_mut(o).hand.push(id).unwrap();id}
fn board(e:&Engine,o:Seat)->State{let mut s=State::default();s.active=o;s.action_player=Some(o);s.hidden_history_exact=true;s.force_state_exact=true;for owner in [Seat::P1,Seat::P2]{let b=add(e,&mut s,owner,"SOR_023");let l=add(e,&mut s,owner,"SOR_014");s.player_mut(owner).base=b;s.player_mut(owner).leader=l;s.player_mut(owner).force_id=s.next_id;s.next_id+=1;}s}
fn start(e:&Engine,s:&mut State,id:CardId){s.source=id;let p=e.available_programs(s,id,"action")[0];e.begin_program(s,p,ProgramContinuation::Finish).unwrap();}
fn click(e:&Engine,s:&mut State,id:CardId){*s=e.apply_ability_action(s,&e.card_action(s,id)).unwrap();}
#[test]fn selected_hand_cost_closed_profile_and_actual_reservation_boundaries(){
 let raw=crate::selected_hand_cost_contract::profile();assert!(crate::selected_hand_cost_contract::prepare(&raw).unwrap());
 let a:crate::ability_ir::Ability=serde_json::from_value(raw["abilities"]["card"][0].clone()).unwrap();assert!(Program::compile(&a).is_err());
 for field in ["className","baseClass","card","abilities","extra"]{let mut v=raw.clone();if field=="card"{v[field]["types"]=json!(["unit","leader"]);}else if field=="abilities"{v[field]["card"][0]["costs"][1]["chooser"]=json!("opponent");}else{v[field]=json!(true);}assert!(crate::selected_hand_cost_contract::prepare(&v).is_err(),"{field}");}
 let mut alias=raw.clone();alias["setCode"]=json!("OPAQUE_ALIAS");assert!(crate::selected_hand_cost_contract::prepare(&alias).is_err());
 for good in [0,65534]{let (ids,p)=crate::selected_hand_cost_contract::compile(good).unwrap();assert_eq!(ids.card,[good as u16]);assert_eq!(p.len(),1);assert!(matches!(p[0].costs.as_slice(),[Cost::SelectCardCost(_),Cost::ExhaustSelf]));}
 for bad in [65535,65536,usize::MAX]{assert!(crate::selected_hand_cost_contract::compile(bad).is_err());}
 assert!(include_str!("ability_ir.rs").contains("if selected_hand_cost {return crate::selected_hand_cost_contract::compile(catalogue.programs.len());}"));
}
#[test]fn selected_hand_cost_target_then_discard_cost_cancellation_and_commit(){
 for backend in [RulesBackend::Auto,RulesBackend::Interpreter]{let mut e=engine();e.rules_backend=backend;for owner in [Seat::P1,Seat::P2]{let mut s=board(&e,owner);let source=unit(&e,&mut s,owner,"ASH_217");let target=unit(&e,&mut s,owner.other(),"SOR_095");let other=unit(&e,&mut s,owner,"SOR_178");let chosen=hand(&e,&mut s,owner,"SOR_095");let spare=hand(&e,&mut s,owner,"SOR_178");let foreign=hand(&e,&mut s,owner.other(),"SOR_095");
 start(&e,&mut s,source);assert_eq!(s.decision,Decision::AbilityTarget);let actions=e.ability_actions(&s);assert!(actions.contains(&Action::button("Cancel","cancel")));assert!(actions.contains(&e.card_action(&s,target)));assert!(actions.contains(&e.card_action(&s,other)));assert!(!actions.contains(&e.card_action(&s,source)));
 click(&e,&mut s,target);assert!(e.selected_hand_cost_prompt(&s));assert_eq!(s.ability_target,target);assert!(!s.card(source).exhausted&&!s.card(target).exhausted);assert_eq!(e.ability_actions(&s),vec![Action::button("Cancel","cancel"),e.card_action(&s,chosen),e.card_action(&s,spare)]);assert!(!e.ability_actions(&s).contains(&e.card_action(&s,foreign)));
 let cancelled=e.apply_ability_action(&s,&Action::button("Cancel","cancel")).unwrap();assert_eq!(cancelled.decision,Decision::Window);assert_eq!(cancelled.player(owner).hand.as_slice(),[chosen,spare]);assert!(!cancelled.card(source).exhausted&&!cancelled.card(target).exhausted);
 let before=s;assert!(e.apply_ability_action(&s,&e.card_action(&s,foreign)).is_err());assert_eq!(s,before);
 click(&e,&mut s,chosen);assert!(s.card(source).exhausted&&s.card(target).exhausted);assert!(!s.card(other).exhausted);assert!(s.player(owner).discard.contains(chosen));assert_eq!(s.player(owner).hand.as_slice(),[spare]);assert_eq!(s.captured_hand_card.id(),0);assert_eq!(s.decision,Decision::Window);assert!(e.available_programs(&s,source,"action").is_empty());
 } }
}
#[test]fn selected_hand_cost_no_effect_still_pays_and_exhausted_selection_is_legal(){
 for backend in [RulesBackend::Auto,RulesBackend::Interpreter]{let mut e=engine();e.rules_backend=backend;for owner in [Seat::P1,Seat::P2]{
  let mut s=board(&e,owner);let source=unit(&e,&mut s,owner,"ASH_217");let chosen=hand(&e,&mut s,owner,"SOR_095");let original=s;
  assert_eq!(e.available_programs(&s,source,"action").len(),1);start(&e,&mut s,source);assert_eq!(s.decision,Decision::AbilityNoEffect);assert_eq!(e.ability_actions(&s),[Action::button("Use it anyway",0),Action::button("Cancel",1)]);
  let cancelled=e.apply_ability_action(&s,&Action::button("Cancel",1)).unwrap();assert_eq!(cancelled,original);
  s=e.apply_ability_action(&s,&Action::button("Use it anyway",0)).unwrap();assert!(e.selected_hand_cost_prompt(&s));assert_eq!(e.ability_actions(&s),[Action::button("Cancel","cancel"),e.card_action(&s,chosen)]);assert!(!s.card(source).exhausted);
  click(&e,&mut s,chosen);assert!(s.card(source).exhausted);assert!(s.player(owner).discard.contains(chosen));assert_eq!(s.decision,Decision::Window);assert_eq!(s.ability_program,0);
  let mut s=board(&e,owner);let source=unit(&e,&mut s,owner,"ASH_217");let target=unit(&e,&mut s,owner.other(),"SOR_095");s.card_mut(target).exhausted=true;let ready=unit(&e,&mut s,owner,"SOR_178");let chosen=hand(&e,&mut s,owner,"SOR_095");start(&e,&mut s,source);assert!(e.ability_actions(&s).contains(&e.card_action(&s,target)));click(&e,&mut s,target);click(&e,&mut s,chosen);assert!(s.card(source).exhausted&&s.card(target).exhausted);assert!(!s.card(ready).exhausted);
  let mut s=board(&e,owner);let source=unit(&e,&mut s,owner,"ASH_217");assert!(e.available_programs(&s,source,"action").is_empty());hand(&e,&mut s,owner,"SOR_095");s.card_mut(source).exhausted=true;assert!(e.available_programs(&s,source,"action").is_empty());
 }}
}
#[test]fn selected_hand_cost_pending_copy_hash_frames_and_strict_import(){
 assert_eq!(std::mem::size_of::<State>(),38312);assert_eq!(std::mem::size_of::<ResolutionContext>(),124);
 let e=engine();for owner in [Seat::P1,Seat::P2]{let mut s=board(&e,owner);let source=unit(&e,&mut s,owner,"ASH_217");let target=unit(&e,&mut s,owner.other(),"SOR_095");let chosen=hand(&e,&mut s,owner,"SOR_178");start(&e,&mut s,source);
 for phase in 0..2{if phase==1 {click(&e,&mut s,target);}let copied=s;assert_eq!(copied.zobrist(),s.zobrist());let context=ResolutionContext::capture(&s);let mut restored=s;restored.ability_target=0;restored.resource_cost_index=9;restored.resource_cost_locked=true;context.restore(&mut restored);assert_eq!(restored,s);let mut snap=e.snapshot(&s);assert_eq!(snap["capturedHandCostPending"],true);assert!(e.load_state(&snap).is_err());snap["actor"]=json!(owner.as_str());assert!(e.load_state(&snap).is_err());}
 let context=ResolutionContext::capture(&s);let mut frame_only=s;frame_only.death_frames[0].context=context;frame_only.death_depth=1;frame_only.ability_program=0;assert_eq!(e.snapshot(&frame_only)["capturedHandCostPending"],true);let mut support_only=s;support_only.support.pending=true;support_only.support.context=context;support_only.ability_program=0;assert_eq!(e.snapshot(&support_only)["capturedHandCostPending"],true);
 let mut cursor=s;cursor.resource_cost_index=1;assert_ne!(cursor.zobrist(),s.zobrist());cursor=s;cursor.resource_cost_locked=true;assert_ne!(cursor.zobrist(),s.zobrist());
 click(&e,&mut s,chosen);assert!(e.snapshot(&s).get("capturedHandCostPending").is_none());assert_eq!(s.captured_hand_card.id(),0);
 }
}
