 let mut e=engine();let mut s=board(&e,Seat::P1);let source=unit(&e,&mut s,Seat::P1,"ASH_217");let p=e.card_programs(&s,source)[0];if let Cost::SelectCardCost(cost)=&mut e.catalogue.as_mut().unwrap().programs[p as usize].costs[0]{cost.chooser="opponent".into();}else{panic!()};let before=s;assert!(e.begin_program(&mut s,p,ProgramContinuation::Finish).is_err());assert_eq!(s,before);
