#[test]fn selected_hand_cost_completed_selected_pool_full_snapshot_and_hash_roundtrip(){
 let catalog:Value=serde_json::from_slice(include_bytes!(concat!(env!("OUT_DIR"),"/catalogue.json"))).unwrap();
 let codes=["ASH_217","SOR_023","SOR_014","SOR_095","SOR_178","TOKEN_SHIELD","TOKEN_CREDIT","TOKEN_THE_FORCE"];
 let cards=codes.iter().map(|code|{let entry=catalog["cards"].as_array().unwrap().iter().find(|e|e["setCode"]==*code).unwrap();let mut card=entry["card"].clone();card["setCode"]=json!(code);card}).collect::<Vec<_>>();
 let pool=json!({"schema":"omni-rs-pool-v1","cards":cards});let bytes=serde_json::to_vec(&catalog).unwrap();
 for backend in [RulesBackend::Auto,RulesBackend::Interpreter]{let mut e=Engine::from_compiled_pool_bytes(&serde_json::to_vec(&pool).unwrap(),&bytes).unwrap();e.rules_backend=backend;for owner in [Seat::P1,Seat::P2]{let mut s=board(&e,owner);s.credit_state_exact=true;let source=unit(&e,&mut s,owner,"ASH_217");let target=unit(&e,&mut s,owner.other(),"SOR_095");let cost=hand(&e,&mut s,owner,"SOR_178");
 let before=e.snapshot(&s);let loaded=e.load_state(&before).unwrap();assert_eq!(e.snapshot(&loaded),before);assert_eq!(loaded.zobrist(),s.zobrist());
 start(&e,&mut s,source);click(&e,&mut s,target);click(&e,&mut s,cost);let snapshot=e.snapshot(&s);let loaded=e.load_state(&snapshot).unwrap();assert_eq!(e.snapshot(&loaded),snapshot);assert_eq!(loaded.zobrist(),s.zobrist());
 for marker in [json!(true),json!(false),Value::Null]{let mut forged=snapshot.clone();forged["capturedHandCostPending"]=marker;assert!(e.load_state(&forged).is_err());}
 }}
}

